/**
 * Shared values for page metadata (Next.js Metadata API) and feeds.
 *
 * Relative URLs below are resolved against `metadataBase` (the live site
 * URL), which the root layout sets.
 */

import type { Metadata } from "next";
import { SITE_NAME } from "./constants";

/** Path of the RSS feed generated by src/app/feed.xml/route.ts. */
export const RSS_FEED_PATH = "/feed.xml";

/**
 * `alternates.types` entry that advertises the RSS feed with
 * `<link rel="alternate" type="application/rss+xml">`.
 *
 * A page that sets `alternates` replaces its parent's `alternates` as a
 * whole, so every page repeats this through {@link pageAlternates}.
 */
export const FEED_ALTERNATE_TYPES = {
  "application/rss+xml": [{ url: RSS_FEED_PATH, title: `${SITE_NAME} News` }],
};

/**
 * Builds a page's `alternates` metadata: its canonical URL plus the RSS feed link.
 *
 * @param path - The page's own path, e.g. "/about" or "/news/2026-05-15-some-post"
 * @returns The `alternates` object for the page's metadata
 */
export function pageAlternates(path: string): NonNullable<Metadata["alternates"]> {
  return { canonical: path, types: FEED_ALTERNATE_TYPES };
}

/**
 * The default share image, src/app/opengraph-image.png (served at
 * /opengraph-image.png). Next.js adds it to every page automatically, except
 * pages that set their own `openGraph`: those must list an image explicitly,
 * because a page's `openGraph` replaces its parent's as a whole.
 * Keep `alt` in sync with src/app/opengraph-image.alt.txt.
 */
export const DEFAULT_OG_IMAGE = {
  url: "/opengraph-image.png",
  width: 1200,
  height: 630,
  type: "image/png",
  alt: `${SITE_NAME}: Bioinformatics & computational biology students and young researchers in Belgium`,
};
